    public static Boolean uploadObjectToGoogleCloudStorage(File file, String path) {
        Boolean isFileUploaded = Boolean.FALSE
        if (path) {
            try {
                Storage storage = StorageOptions.getDefaultInstance().getService()
                String bucketName = Holders.getFlatConfig().get("google.cloud.storage.bucket.name")
                BlobId blobId = BlobId.of(bucketName, path)
                BlobInfo blobInfo = BlobInfo.newBuilder(blobId).build()
                storage.create(blobInfo, Files.readAllBytes(file.toPath()))
                isFileUploaded = Boolean.TRUE
            } catch (Exception e) {
                log.error("Exception while uploading file to Google Cloud Storage ==>> ${e.message}", e)
            }
        }
        isFileUploaded
    }

    public static InputStream downloadObjectFromGoogleCloudStorage(String path) {
        InputStream inputStream = null
        if (path) {
            File file = null
            try {
                Storage storage = StorageOptions.getDefaultInstance().getService()
                String bucketName = Holders.getFlatConfig().get("google.cloud.storage.bucket.name")
                BlobId blobId = BlobId.of(bucketName, path)
                com.google.cloud.storage.Blob blob = storage.get(blobId)
                if (blob != null) {
                    file = File.createTempFile(RandomStringUtils.randomAlphanumeric(6), ".pdf")
                    blob.downloadTo(Paths.get(file.path))
                    inputStream = file.newDataInputStream()
                }
            } catch (Exception e) {
                log.error("Exception while downloading file from Google Cloud Storage ==>> ${e.message}", e)
            } finally {
                if (file)
                    file.delete()
            }
        }
        inputStream
    }

